    if not token or not token.isascii() or not token.isdigit():
        raise ConfigError("invalid uint16 decimal")
    digits = token.lstrip("0") or "0"
    if len(digits) > 5:
        raise ConfigError("uint16 out of range")
    value = int(digits)
    if value > 0xFFFF:
        raise ConfigError("uint16 out of range")
    return value


def _master_parse_uint8(token):
