def _master_is_printable(ch):
    """主文件引号串内可直接书写的可打印 ASCII：0x20..0x7E。"""
    return 0x20 <= ord(ch) <= 0x7E


def _master_parse_quoted(rest, pos):
    """从 rest[pos]（须恰为双引号）解析一个引号串，返回 (bytes, 下一偏移)。

    串内仅接受可打印 ASCII（0x20..0x7E），转义仅 "\\"、"\"" 或
    三位十进制 "\\DDD"（000..255）；未终止或转义非法抛 ConfigError。
    """
    length = len(rest)
    if pos >= length or rest[pos] != '"':
        raise ConfigError("quoted string must start with a quote")
    pos += 1
    out = bytearray()
    while True:
        if pos >= length:
            raise ConfigError("quoted string not terminated")
        ch = rest[pos]
        if ch == '"':
            return bytes(out), pos + 1
        if ch == "\\":
            if pos + 1 >= length:
                raise ConfigError("bad escape")
            escaped = rest[pos + 1]
            if escaped == "\\" or escaped == '"':
                out.append(ord(escaped))
                pos += 2
            else:
                if pos + 4 > length:
                    raise ConfigError("bad escape")
                digits = rest[pos + 1:pos + 4]
                if not digits.isascii() or not digits.isdigit():
                    raise ConfigError("bad escape")
                value = int(digits)

def _decode_cname_target(rdata):
    """把 CNAME rdata 按未压缩绝对名线格式解码为小写标签列表。

    标签 1–63 字节、0 结尾、总长 ≤255；禁止压缩指针、尾随内容与非法字符。
    """
    if len(rdata) > _MAX_NAME_WIRE_LEN:
        raise RecordError("cname rdata too long")
    labels = []
    pos = 0
    while True:
        if pos >= len(rdata):
            raise RecordError("cname rdata not terminated")
        length = rdata[pos]
        if length == 0:
            pos += 1
            break
        if length > _MAX_LABEL_LEN:
            raise RecordError("cname rdata bad label length")
        pos += 1
        if pos + length > len(rdata):
            raise RecordError("cname rdata truncated")
        try:
            label = rdata[pos:pos + length].decode("ascii")
        except UnicodeDecodeError:
            raise RecordError("cname rdata label not ascii") from None
        if any(ch not in _LABEL_CHARS for ch in label):
            raise RecordError("cname rdata invalid label character")
        labels.append(label.lower())
        pos += length
    if pos != len(rdata):
        raise RecordError("cname rdata trailing bytes")
    return labels


def _encode_cname_target(labels):
    """把标签列表重编码为未压缩绝对名线格式。"""
    out = bytearray()
    for label in labels:
        out.append(len(label))
        out.extend(label.encode("ascii"))
    out.append(0)
    return bytes(out)


def _read_soa_name(rdata, pos):
    """按 CNAME 目标规范解码 rdata pos 处的未压缩绝对名，返回下一偏移。

    任何格式问题都返回 None，不抛异常。
    """
    wire_len = 1  # 根终止符占 1 字节
    while True:
        if pos >= len(rdata):
            return None
        length = rdata[pos]
        if length == 0:
            return pos + 1
        if length > _MAX_LABEL_LEN:  # 含压缩指针形态
            return None
        pos += 1
        if pos + length > len(rdata):
            return None
        try:
            label = rdata[pos:pos + length].decode("ascii")
        except UnicodeDecodeError:
            return None
        if any(ch not in _LABEL_CHARS for ch in label):
            return None
        wire_len += length + 1
        if wire_len > _MAX_NAME_WIRE_LEN:
            return None
        pos += length


